contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address attacker, address newOwner) public {
        require(attacker != address(this));
        address initialOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(attacker != initialOwner);

        bool reverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.owner() == initialOwner);
    }

    receive() external payable {}
}

